#!/usr/bin/env node
/**
 * Solaria BoQ — one-file installer (v4: multi-project dashboard + business-day planning).
 *
 * HOW TO USE (Windows / Mac / Linux):
 *   1. Put this file in your project root:  C:\\Users\\darma\\solaria-boq
 *   2. Open a terminal there and run:       node sbf.mjs
 *   3. It writes the entire src/ tree (plus README.md + FILE_LIST.md), overwriting old files.
 *   4. Back in the browser running "npm run dev", hard-refresh:  Ctrl+Shift+R  (Cmd+Shift+R on Mac).
 *
 * This writes files RELATIVE TO ITS OWN LOCATION, so it can't half-update the tree the way
 * hand-copying individual files did. If "npm run dev" isn't already running, start it after.
 *
 * NOTE: this build bumps localStorage to key "solaria_boq_db_v4" — it reseeds fresh demo data,
 * so any clicking-around you did on the old seed is wiped (you said there's no real data yet).
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const HERE = path.dirname(fileURLToPath(import.meta.url));

// [relativePath, base64Content]
const FILES = [
  ["FILE_LIST.md", ""],
  ["README.md", ""],
  ["src/App.jsx", ""],
  ["src/components/Modal.jsx", ""],
  ["src/components/NewProjectModal.jsx", ""],
  ["src/components/PrModal.jsx", ""],
  ["src/components/ReceiveModal.jsx", ""],
  ["src/components/Sidebar.jsx", ""],
  ["src/components/ui.jsx", ""],
  ["src/data/seed.js", ""],
  ["src/engine/format.js", ""],
  ["src/engine/match.js", ""],
  ["src/engine/reconcile.js", ""],
  ["src/engine/schedule.js", ""],
  ["src/index.css", ""],
  ["src/main.jsx", ""],
  ["src/pages/BoqPage.jsx", ""],
  ["src/pages/CataloguePage.jsx", ""],
  ["src/pages/DashboardPage.jsx", ""],
  ["src/pages/MandorsPage.jsx", ""],
  ["src/pages/MaterialTypesPage.jsx", ""],
  ["src/pages/Overview.jsx", ""],
  ["src/pages/ProjectCataloguePage.jsx", ""],
  ["src/pages/PurchaseRequestsPage.jsx", ""],
  ["src/pages/ReconciliationPage.jsx", ""],
  ["src/pages/SchedulePage.jsx", ""],
  ["src/pages/SuppliersPage.jsx", ""],
  ["src/pages/UsersPage.jsx", ""],
  ["src/store/StoreContext.jsx", ""],
  ["src/theme.js", ""],
];

let written = 0;
for (const [rel, b64] of FILES) {
  const dest = path.join(HERE, rel);
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.writeFileSync(dest, Buffer.from(b64, 'base64'));
  console.log('  wrote ' + rel);
  written++;
}

console.log('\n✓ Wrote ' + written + ' files into ' + HERE);
console.log('\nNext:');
console.log('  • If "npm run dev" is running, hard-refresh the browser: Ctrl+Shift+R');
console.log('  • If not, run:  npm install  (first time)  then  npm run dev');
console.log('\nYou\'ll land on the new "This Week" dashboard. The old per-project view is now "Overview".');
